{
  "a_requests": [
    {
      "a_request": "R1",
      "b_asked": "서울시 공영주차장에서 경차 주차요금 할인 여부",
      "c_basis": "DIRECT",
      "d_claims": [
        {
          "a_text": "서울특별시 주차장 설치 및 관리 조례 제7조제1항제2호에 따라, 시장은 「자동차관리법」 제3조 및 같은 법 시행규칙 제2조에 따른 경형자동차(경차)에 대하여 주차요금의 100분의 50을 할인할 수 있다. 다만, 지하철 환승주차장에서 환승목적으로 주차하는 경형자동차는 주차요금의 100분의 80을 할인하되, 1일 1회 주차의 경우 최초 3시간까지의 주차요금을 면제한다.",
          "b_ids": "주차장:제7조제1항제2호, 주차장:제7조제1항제2호단서"
        }
      ],
      "e_status": "ANSWERED"
    }
  ]
}
